INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000010','中州','许州城','家族内院','road','家族设施沿内院两侧分布，向北通往后山。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000011','中州','许州城','宗祠','building','祭拜先祖，领取宗祠修炼加成。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000012','中州','许州城','成员部屋','building','家族成员居住和休息的房间。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000013','中州','许州城','家族仓库','building','存放族内公共材料、丹药与器物。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000014','中州','许州城','执法堂','building','处理族规与家族内部纠纷。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000015','中州','许州城','练功房','building','族人练习功法、交流修行心得。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000016','中州','许州城','家族炼丹房','building','使用炉鼎和药草炼制丹药。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000017','中州','许州城','家族炼器房','building','使用矿石、铁砧与铁锤打造器物。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000018','中州','许州城','家族符纸房','building','加工纸材、符纸，制作符箓。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000019','中州','许州城','后山','wilderness','族地后山，灵脉、灵矿与灵田分布于此。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000020','中州','许州城','家族灵脉','wilderness','在灵脉旁打坐，修炼收益增加50%；离开后停止加成。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000021','中州','许州城','家族灵矿','wilderness','族内基础灵矿产区。');
