INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000030','中州','许州城','百姓街','road','百姓往来、挑担摆摊，巷内有民居和生活铺子。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000031','中州','许州城','民居','building','普通百姓的屋舍，灶火与日常生活气息。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000032','中州','许州城','街边摊市','road','百姓出售蔬果、饭食、布匹与日用品。');
