INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000035','中州','许州城','传送阵','building','同州城池按距离收费；跨州需专线，费用远高于州内传送。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000036','中州','许州城','灵宝坊','building','云游商队定期停靠，货少价高，远产地的材料更贵。');
