INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000040','中州','许州城','监狱','building','随意杀人受到天道惩罚；依情节拘禁1日至30日。');
INSERT INTO public.fc_world_rooms(id,state_name,city_name,name,kind,description) VALUES('10000000-0000-0000-0000-000000000041','中州','许州城','驿站','building','搭乘马车或小云舟前往其他城池。');
